            for Index in ipairs(PlaceConfig.WAYPOINTS) do
                table.insert(WaypointOptions, "Waypoint #" .. Index)
            end

            for Index in ipairs(PlaceConfig.FARM_ZONES) do
                table.insert(ZoneOptions, ZoneOptionLabel(Index))
            end

