            for _, Name in ipairs(AICCombat.GetDetectedEnemyEntities()) do
                table.insert(Options, Name)
            end

            for _, Name in ipairs(CONFIG.TARGET_ENTITY_PRIORITY or {}) do
                if not table.find(Options, Name) then
                    table.insert(Options, Name)
                end
            end

            for Index = #Options, 1, -1 do
